<?php namespace App\Services; use App\Models\Unit; use App\Repositories\Unit\UnitRepositoryInterface; class UnitService {public function __construct(private UnitRepositoryInterface $repo){} public function list(array $f){return $this->repo->paginate($f);} public function create(array $d):Unit{return $this->repo->create($d);} public function update(Unit $u,array $d):Unit{return $this->repo->update($u,$d);} public function delete(Unit $u):void{$this->repo->delete($u);}}